const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test.beforeEach(async ({ page }) => {
  await page.goto("index.html");
  await page.getByRole("button", { name: "Start" }).click();
});
test("AC-012 the heading shows after start", async ({ page }) => {
  await expect(page.getByRole("heading", { name: "Spike page" })).toBeVisible();
});

